using System.Globalization;
using System.Security.Cryptography;
using System.Text;

namespace Blux.UI.Build.Fonts
{
    internal sealed class FontBuildOptions
    {
        public List<FontSpec> Specs { get; set; } = new List<FontSpec>();
        public List<string> ProviderPriority { get; set; } = new List<string> { "google", "bunny", "fontsource" };
        public string CacheDir { get; set; } = "";
        public string OutputDir { get; set; } = "";
        /// <summary>Route of the generated files, relative to the site root.</summary>
        public string UrlBase { get; set; } = "_blux/fonts";
        public TimeSpan CacheMaxAge { get; set; } = TimeSpan.FromDays(7);
        /// <summary>Never touch the network: everything must already be in the cache.</summary>
        public bool Offline { get; set; }
        public Action<string> Info { get; set; } = _ => { };
        public Action<string> Warn { get; set; } = _ => { };
    }

    internal sealed class FontBuildResult
    {
        /// <summary>File names inside the output folder that the app serves (the stylesheet included).</summary>
        public List<string> Files { get; } = new List<string>();
        public List<string> Errors { get; } = new List<string>();
        public string ManifestJson { get; set; } = "";
        public bool UpToDate { get; set; }
    }

    internal static class FontBuilder
    {
        public const string CssFileName = "blux.fonts.css";
        public const string ManifestFileName = "blux.fonts.json";
        private const string StampFileName = ".stamp";
        private const string Version = "1";

        public const string DefaultSans = "-apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, \"Helvetica Neue\", \"Noto Sans\", Arial, sans-serif, \"Apple Color Emoji\", \"Segoe UI Emoji\", \"Segoe UI Symbol\", \"Noto Color Emoji\"";
        public const string DefaultMono = "ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, \"Liberation Mono\", \"Courier New\", monospace";

        public static FontBuildResult Run(FontBuildOptions options, INetwork network)
        {
            var result = new FontBuildResult();
            Directory.CreateDirectory(options.OutputDir);

            var stamp = Stamp(options);
            var stampPath = Path.Combine(options.OutputDir, StampFileName);
            var cssPath = Path.Combine(options.OutputDir, CssFileName);
            var manifestPath = Path.Combine(options.OutputDir, ManifestFileName);
            if (File.Exists(stampPath) && File.Exists(cssPath) && File.Exists(manifestPath) && File.ReadAllText(stampPath) == stamp)
            {
                var files = Directory.EnumerateFiles(options.OutputDir).Select(Path.GetFileName).Where(n => n != StampFileName && n != ManifestFileName).OrderBy(n => n, StringComparer.Ordinal);
                result.Files.AddRange(files!);
                result.ManifestJson = File.ReadAllText(manifestPath);
                result.UpToDate = true;
                return result;
            }

            var downloader = new CachedDownloader(network, options.CacheDir, options.CacheMaxAge, options.Info, options.Offline);
            var css = new StringBuilder("/* Generated by Blux.UI at build time from the BluxFont items of the project. Do not edit. */\n");
            var written = new Dictionary<string, byte[]>(StringComparer.Ordinal);
            var roles = new List<(string Role, string Value, string Family)>();
            var manifestFonts = new List<string>();

            foreach (var spec in options.Specs)
            {
                try
                {
                    var (provider, faces) = ResolveFamily(spec, options, downloader);
                    foreach (var face in faces)
                    {
                        face.Bytes = face.LocalPath.Length > 0 ? File.ReadAllBytes(face.LocalPath) : downloader.GetBytes(face.Url);
                        face.FileName = FileNameOf(face);
                        written[face.FileName] = face.Bytes;
                    }

                    var ordered = faces.OrderBy(f => f.Style == "normal" ? 0 : 1).ThenBy(f => f.Weight.Min)
                        .ThenBy(f => f.Subset == null ? 0 : Math.Max(0, spec.Subsets.IndexOf(f.Subset))).ToList();
                    css.Append("\n/* ").Append(spec.Family).Append(" (").Append(provider).Append(") */\n");
                    foreach (var face in ordered)
                    {
                        css.Append(FaceCss(face, spec.Display));
                    }

                    var fallbackName = "";
                    try
                    {
                        var measured = PickForMetrics(ordered);
                        var metrics = FontMetrics.Read(measured.Bytes!);
                        css.Append(FallbackFace.Css(spec.Family, metrics, SystemFont.For(spec.EffectiveCategory)));
                        fallbackName = spec.Family + " Fallback";
                    }
                    catch (FontException e)
                    {
                        options.Info($"No fallback face for '{spec.Family}': {e.Message}");
                    }

                    if (spec.Role.Length > 0)
                    {
                        var stack = new StringBuilder(FontCss.Quote(spec.Family));
                        if (fallbackName.Length > 0) stack.Append(", ").Append(FontCss.Quote(fallbackName));
                        stack.Append(", ").Append(spec.Role == "mono" ? DefaultMono : DefaultSans);
                        roles.Add((spec.Role, stack.ToString(), spec.Family));
                    }

                    var preload = spec.PreloadEnabled ? PickPreload(ordered, spec) : null;
                    manifestFonts.Add("{\"family\":" + Json(spec.Family) + ",\"role\":" + Json(spec.Role) + ",\"provider\":" + Json(provider)
                        + ",\"fallback\":" + (fallbackName.Length > 0 ? "true" : "false")
                        + ",\"preload\":[" + (preload == null ? "" : Json(options.UrlBase + "/" + preload.FileName)) + "]}");
                }
                catch (BuildToolException e)
                {
                    result.Errors.Add(e.Message);
                }
            }

            if (roles.Count > 0)
            {
                css.Append("\n:root {\n");
                foreach (var role in roles.Select(r => r.Role).Distinct())
                {
                    var chosen = roles.First(r => r.Role == role);
                    foreach (var other in roles.Where(r => r.Role == role).Skip(1))
                    {
                        options.Warn($"Two fonts have the role '{role}' ('{chosen.Family}' and '{other.Family}'): only '{chosen.Family}' is used for --blux-font-{role}.");
                    }
                    css.Append("  --blux-font-").Append(role).Append(": ").Append(chosen.Value).Append(";\n");
                }
                css.Append("}\n");
            }

            result.ManifestJson = "{\"v\":1,\"css\":" + Json(options.UrlBase + "/" + CssFileName) + ",\"fonts\":[" + string.Join(",", manifestFonts) + "]}";

            // Write everything, then remove what an earlier build left behind.
            foreach (var pair in written) WriteIfChanged(Path.Combine(options.OutputDir, pair.Key), pair.Value);
            WriteIfChanged(cssPath, Encoding.UTF8.GetBytes(css.ToString()));
            WriteIfChanged(manifestPath, Encoding.UTF8.GetBytes(result.ManifestJson));
            var keep = new HashSet<string>(written.Keys) { CssFileName, ManifestFileName, StampFileName };
            foreach (var file in Directory.EnumerateFiles(options.OutputDir))
            {
                if (!keep.Contains(Path.GetFileName(file))) File.Delete(file);
            }
            result.Files.AddRange(written.Keys.OrderBy(n => n, StringComparer.Ordinal));
            result.Files.Add(CssFileName);
            if (result.Errors.Count == 0)
            {
                File.WriteAllText(stampPath, stamp);
            }
            else if (File.Exists(stampPath))
            {
                File.Delete(stampPath);
            }
            return result;
        }

        internal static (string Provider, List<FontFace> Faces) ResolveFamily(FontSpec spec, FontBuildOptions options, CachedDownloader downloader)
        {
            var names = spec.Provider.Length > 0 ? new List<string> { spec.Provider }
                : spec.Src.Length > 0 ? new List<string> { "local" }
                : options.ProviderPriority;
            var failures = new List<string>();
            foreach (var name in names)
            {
                IFontProvider provider = name switch
                {
                    "google" => new GoogleProvider(),
                    "bunny" => new BunnyProvider(),
                    "fontsource" => new FontsourceProvider(),
                    "local" => new LocalProvider(),
                    _ => throw new FontException($"Font '{spec.Family}': unknown provider '{name}'. Use google, bunny, fontsource or local."),
                };
                try
                {
                    return (name, provider.Resolve(spec, downloader).ToList());
                }
                catch (BuildToolException e)
                {
                    failures.Add(names.Count == 1 ? e.Message : $"{name}: {e.Message}");
                }
            }
            throw new FontException(names.Count == 1 ? failures[0] : $"Font '{spec.Family}' could not be resolved. " + string.Join(" ", failures));
        }

        /// <summary>The face the fallback is measured on: upright, closest to weight 400, in the first subset that has letters.</summary>
        internal static FontFace PickForMetrics(IReadOnlyList<FontFace> faces)
        {
            var candidates = faces.Where(f => f.Style == "normal").DefaultIfEmpty(faces[0]).ToList();
            var subset = candidates.Any(f => f.Subset == "latin") ? "latin" : candidates.First().Subset;
            return candidates.Where(f => f.Subset == subset).OrderBy(f => Distance(f.Weight, 400)).First();
        }

        /// <summary>One face to preload: upright, closest to weight 400, latin (or the first requested subset).</summary>
        internal static FontFace? PickPreload(IReadOnlyList<FontFace> faces, FontSpec spec)
        {
            var woff2 = faces.Where(f => f.Extension == "woff2" && f.Style == "normal").ToList();
            if (woff2.Count == 0) woff2 = faces.Where(f => f.Extension == "woff2").ToList();
            if (woff2.Count == 0) return null;
            var subset = woff2.Any(f => f.Subset == "latin") ? "latin" : spec.Subsets.FirstOrDefault(s => woff2.Any(f => f.Subset == s)) ?? woff2.First().Subset;
            return woff2.Where(f => f.Subset == subset).OrderBy(f => Distance(f.Weight, 400)).First();
        }

        private static int Distance(WeightSpec w, int target) => target < w.Min ? w.Min - target : target > w.Max ? target - w.Max : 0;

        internal static string FaceCss(FontFace face, string display)
        {
            var sb = new StringBuilder("@font-face {\n");
            sb.Append("  font-family: ").Append(FontCss.Quote(face.Family)).Append(";\n");
            sb.Append("  font-style: ").Append(face.Style).Append(";\n");
            sb.Append("  font-weight: ").Append(face.Weight).Append(";\n");
            sb.Append("  font-display: ").Append(display).Append(";\n");
            sb.Append("  src: url(").Append(FontCss.Quote(face.FileName)).Append(") format(").Append(FontCss.Quote(FontCss.Format(face.Extension))).Append(");\n");
            if (!string.IsNullOrEmpty(face.UnicodeRange)) sb.Append("  unicode-range: ").Append(face.UnicodeRange).Append(";\n");
            sb.Append("}\n");
            return sb.ToString();
        }

        internal static string FileNameOf(FontFace face)
        {
            string hash;
            using (var sha = SHA256.Create())
            {
                hash = BitConverter.ToString(sha.ComputeHash(face.Bytes!), 0, 4).Replace("-", "").ToLowerInvariant();
            }
            var weight = face.Weight.IsRange ? $"{face.Weight.Min}-{face.Weight.Max}" : face.Weight.Min.ToString(CultureInfo.InvariantCulture);
            var parts = new List<string> { FontCss.Slug(face.Family), weight, face.Style };
            if (!string.IsNullOrEmpty(face.Subset)) parts.Add(FontCss.Slug(face.Subset!));
            return string.Join("-", parts) + "." + hash + "." + face.Extension;
        }

        private static string Stamp(FontBuildOptions options)
        {
            var sb = new StringBuilder(Version).Append('\n');
            sb.Append(string.Join(",", options.ProviderPriority)).Append('\n').Append(options.UrlBase).Append('\n');
            foreach (var spec in options.Specs)
            {
                sb.Append(spec.Signature()).Append('\n');
                if (spec.Src.Length > 0 && Directory.Exists(spec.Src))
                {
                    foreach (var file in Directory.EnumerateFiles(spec.Src, "*", SearchOption.AllDirectories).OrderBy(f => f, StringComparer.Ordinal))
                    {
                        var info = new FileInfo(file);
                        sb.Append(file).Append(':').Append(info.Length).Append(':').Append(info.LastWriteTimeUtc.Ticks).Append('\n');
                    }
                }
            }
            using var sha = SHA256.Create();
            return BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(sb.ToString()))).Replace("-", "").ToLowerInvariant();
        }

        private static void WriteIfChanged(string path, byte[] bytes)
        {
            if (File.Exists(path) && File.ReadAllBytes(path).SequenceEqual(bytes)) return;
            File.WriteAllBytes(path, bytes);
        }

        internal static string Json(string value)
        {
            var sb = new StringBuilder("\"");
            foreach (var c in value)
            {
                switch (c)
                {
                    case '"': sb.Append("\\\""); break;
                    case '\\': sb.Append("\\\\"); break;
                    case '\n': sb.Append("\\n"); break;
                    default:
                        if (c < 0x20) sb.Append("\\u").Append(((int)c).ToString("x4", CultureInfo.InvariantCulture));
                        else sb.Append(c);
                        break;
                }
            }
            return sb.Append('"').ToString();
        }

        /// <summary>Parses the items of the project (the metadata documented in the Fonts guide) into specs.</summary>
        public static FontSpec ParseSpec(string family, IDictionary<string, string> metadata, string projectDirectory)
        {
            string Get(string key) => metadata.TryGetValue(key, out var v) ? v.Trim() : "";
            var spec = new FontSpec { Family = family.Trim() };
            if (spec.Family.Length == 0) throw new FontException("A BluxFont item has no family name.");

            var role = Get("Role").ToLowerInvariant();
            if (role.Length > 0 && role != "sans" && role != "mono" && role != "none")
            {
                throw new FontException($"Font '{spec.Family}': Role '{role}' is not supported. Use sans, mono, or leave it empty.");
            }
            spec.Role = role == "none" ? "" : role;
            spec.Provider = Get("Provider").ToLowerInvariant();
            if (spec.Provider == "auto") spec.Provider = "";
            if (Get("Weights").Length > 0) spec.Weights = Split(Get("Weights")).Select(w => WeightSpec.Parse(w, spec.Family)).ToList();
            if (Get("Styles").Length > 0) spec.Styles = Split(Get("Styles")).Select(s => s.ToLowerInvariant()).ToList();
            if (Get("Subsets").Length > 0) spec.Subsets = Split(Get("Subsets")).Select(s => s.ToLowerInvariant()).ToList();
            if (Get("Display").Length > 0) spec.Display = Get("Display").ToLowerInvariant();
            if (new[] { "auto", "block", "swap", "fallback", "optional" }.All(d => d != spec.Display))
            {
                throw new FontException($"Font '{spec.Family}': Display '{spec.Display}' is not a font-display value (auto, block, swap, fallback, optional).");
            }
            if (Get("Preload").Length > 0)
            {
                if (!bool.TryParse(Get("Preload"), out var preload)) throw new FontException($"Font '{spec.Family}': Preload must be true or false.");
                spec.Preload = preload;
            }
            if (Get("Src").Length > 0)
            {
                spec.Src = Path.GetFullPath(Path.Combine(projectDirectory, Get("Src")));
                if (spec.Provider.Length == 0) spec.Provider = "local";
            }
            var category = Get("Category").ToLowerInvariant();
            if (category.Length > 0 && category != "sans" && category != "serif" && category != "mono")
            {
                throw new FontException($"Font '{spec.Family}': Category '{category}' is not supported. Use sans, serif or mono.");
            }
            spec.Category = category;
            return spec;
        }

        private static IEnumerable<string> Split(string value) =>
            value.Split(new[] { ';', ',' }, StringSplitOptions.RemoveEmptyEntries).Select(v => v.Trim()).Where(v => v.Length > 0);
    }
}
